class Solution {
public:
    int digArtifacts(int n, vector<vector<int>>& artifacts, vector<vector<int>>& dig) {
        vector<vector<int>> grid(n, vector<int>(n, -1));
        vector<int> rem;
        for (int i = 0; i < (int)artifacts.size(); ++i) {
            auto& a = artifacts[i];
            rem.push_back((a[2] - a[0] + 1) * (a[3] - a[1] + 1));
            for (int r = a[0]; r <= a[2]; ++r)
                for (int c = a[1]; c <= a[3]; ++c)
                    grid[r][c] = i;
        }
        for (auto& d : dig)
            if (grid[d[0]][d[1]] >= 0)
                --rem[grid[d[0]][d[1]]];
        return count(rem.begin(), rem.end(), 0);
    }
};

