class Solution {
    public int digArtifacts(int n, int[][] artifacts, int[][] dig) {
        int[][] grid = new int[n][n];
        for (int[] row : grid) java.util.Arrays.fill(row, -1);
        List<Integer> rem = new ArrayList<>();
        for (int i = 0; i < artifacts.length; ++i) {
            int[] a = artifacts[i];
            rem.add((a[2] - a[0] + 1) * (a[3] - a[1] + 1));
            for (int r = a[0]; r <= a[2]; ++r)
                for (int c = a[1]; c <= a[3]; ++c)
                    grid[r][c] = i;
        }
        for (int[] d : dig)
            if (grid[d[0]][d[1]] >= 0)
                rem.set(grid[d[0]][d[1]], rem.get(grid[d[0]][d[1]]) - 1);
        int ans = 0;
        for (int x : rem) if (x == 0) ans++;
        return ans;
    }
}

