var digArtifacts = function(n, artifacts, dig) {
    const grid = Array.from({length: n}, () => new Array(n).fill(-1));
    const rem = [];
    artifacts.forEach(([r1, c1, r2, c2], i) => {
        rem.push((r2 - r1 + 1) * (c2 - c1 + 1));
        for (let r = r1; r <= r2; ++r)
            for (let c = c1; c <= c2; ++c)
                grid[r][c] = i;
    });
    for (const [r, c] of dig)
        if (grid[r][c] >= 0) rem[grid[r][c]]--;
    return rem.filter(x => x === 0).length;
};

