        Set<Integer> dug = new HashSet<>();
        for (int[] d : dig) dug.add(d[0] * n + d[1]);
        int ans = 0;
        for (int[] a : artifacts) {
            boolean ok = true;
            outer:
            for (int r = a[0]; r <= a[2]; ++r)
                for (int c = a[1]; c <= a[3]; ++c)
                    if (!dug.contains(r * n + c)) { ok = false; break outer; }
            if (ok) ans++;
        }
        return ans;
    }
}

